"use client";
import { usePremiumUpgrade } from "@/components/premium-upgrade-provider";
import { Button } from "@/components/ui/button";
import { useId } from "react";
import { UpgradePrompt } from "@/components/upgrade-prompt";
export function FeatureLock({
  feature,
  upgradeFeature,
  id,
  compact = false,
  planLabel = "Paid",
}: {
  feature: string;
  upgradeFeature?: import("./premium-upgrade-dialog").UpgradeFeature;
  id?: string;
  compact?: boolean;
  planLabel?: "Paid" | "Premium";
}) {
  const upgrade = usePremiumUpgrade();
  const generatedId = useId();
  const descriptionId = id ?? generatedId;
  if (compact)
    return (
      <span id={descriptionId} className="sr-only">
        {feature} · {planLabel} required.
      </span>
    );
  return (
    <div role="group" aria-describedby={descriptionId}>
      <div id={descriptionId}>
        <UpgradePrompt planLabel={planLabel}>
          {feature} · {planLabel} required.
        </UpgradePrompt>
      </div>
      <Button
        type="button"
        variant="outline"
        className="cursor-pointer"
        onClick={(event) =>
          upgrade({ feature: upgradeFeature, trigger: event.currentTarget })
        }
      >
        Upgrade to Premium
      </Button>
    </div>
  );
}
